<script module lang="ts">
/**
 * The page for a query and its results (`design/archetypes/search-page.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/search-page.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { type Snippet } from 'svelte'

import { Render, joinSlot } from '@polymorph/svelte'
import styles from '@polymorph/recipes/archetypes/search-page.module.css'
import EmptyState from '../structure/EmptyState.svelte'
import Inline from '../layout/Inline.svelte'
import PageHeader from '../structure/PageHeader.svelte'
import type { EmptyStateProps } from '../structure/EmptyState.svelte'

export interface SearchPageProps {
  /**
   * Vocabulary controls, including the page's one primary action.
   */
  actions?: Snippet
  /**
   * Groups of results, each a Heading, a List and a CursorPagination. None before a query.
   */
  children?: Snippet
  description?: string
  /**
   * The query found nothing: the results region holds the empty state.
   */
  empty?: boolean
  /**
   * The empty state, required so the page always says what it shows when a query finds nothing.
   */
  emptyState: EmptyStateProps
  /**
   * A FilterBar, or `sm` controls, under the field.
   */
  filters?: Snippet
  /**
   * Makes the landmark a real `<form>`, so Enter in the field submits. Without it the
   * application searches as the reader types.
   */
  onSubmit?: () => void
  /**
   * A search is running: the results region is busy, and the last results stay in it.
   */
  pending?: boolean
  /**
   * The query field: a SearchInput, or a FormField with an Input whose `trailing` is a submit
   * Button.
   */
  search: Snippet
  /**
   * The search landmark's name. A shell often has a search of its own, and two landmarks of one
   * kind are told apart only by their names.
   */
  searchLabel: string
  title: string
}
</script>

<script lang="ts">
let {
  actions,
  children,
  description,
  empty = false,
  emptyState,
  filters,
  onSubmit,
  pending = false,
  search,
  searchLabel,
  title,
}: SearchPageProps = $props()
const joined = joinSlot(undefined, () => ({}))
const listening = {
  get submit() {
    return onSubmit !== undefined
  },
}
const slots = {
  get actions() {
    return actions
  },
  get default() {
    return children
  },
  get filters() {
    return filters
  },
  get search() {
    return search
  },
}
const submit = $derived((event: Event) => {
  event.preventDefault()
  onSubmit?.()
})
</script>

{@render joined.start?.()
}{#if joined.shown
  }<div
    class={styles.page}
    data-empty={(empty) ? '' : undefined}
    data-pending={(pending) ? '' : undefined}
    data-member="search-page"
    >{#snippet actionsOfPageHeader1()}{@render actions?.()}{/snippet
    }<PageHeader {title} {description} actions={slots.actions ? actionsOfPageHeader1 : undefined}
    />{#if listening.submit
      }<form
        class={styles.search}
        role="search"
        aria-label={searchLabel}
        data-search-page-part="search"
        novalidate={true}
        onsubmit={(event) => { submit(event) }}
        >{@render search?.()
        }{#if slots.filters}<Inline gap={3} wrap={true}>{@render filters?.()}</Inline>{/if
      }</form
    >{:else
      }<div
        class={styles.search}
        role="search"
        aria-label={searchLabel}
        data-search-page-part="search"
        >{@render search?.()
        }{#if slots.filters}<Inline gap={3} wrap={true}>{@render filters?.()}</Inline>{/if
      }</div
    >{/if
    }<div
      class={styles.results}
      aria-busy={pending ? true : undefined}
      data-search-page-part="results"
      >{#if empty
        }{#snippet actionOfEmptyState2()}<Render node={emptyState.action} />{/snippet
        }{#snippet secondaryActionOfEmptyState3()
          }<Render node={emptyState.secondaryAction}
        />{/snippet
        }<EmptyState
          icon={emptyState.icon}
          title={emptyState.title}
          description={emptyState.description}
          action={emptyState.action !== undefined ? actionOfEmptyState2 : undefined}
          secondaryAction={emptyState.secondaryAction !== undefined ? secondaryActionOfEmptyState3 : undefined}
      />{:else
        }{@render children?.()
      }{/if
    }</div
  ></div
>{/if
}{@render joined.end?.()}
